17	/**
18	 * The exact receipt paths appended after the zero-service-worker
19	 * reconciliation, rolled back so the earlier publication transactions still
20	 * replay against their real predecessor.
21	 */
22	const POST_ZERO_SW_RECEIPT_PATHS = new Set<unknown>([
23		REACT_PAPERCUPS_RECEIPT_PATH,
24		WITNESS_REACT_PAPERCUPS_RECEIPT_PATH,
25		REACT_HOSPITALRUN_RECEIPT_PATH,
26		WITNESS_REACT_HOSPITALRUN_RECEIPT_PATH,
27		WITNESS_ANGULAR_FACTORIOLAB_RECEIPT_PATH,
28		WITNESS_ANGULAR_JIRA_CLONE_RECEIPT_PATH,
29		WITNESS_REACT_MEMOS_RECEIPT_PATH,
30		WITNESS_NEXT_KILLEDBYGOOGLE_V3_RECEIPT_PATH,
31		WITNESS_REACT_LINKFREE_RECEIPT_PATH,
32	]);
33	
34	/**
35	 * The canonical aggregate with the Papercups pair, the HospitalRun pair, and
36	 * the factoriolab, jira-clone, memos, killedbygoogle v3 and LinkFree members
37	 * rolled back.
38	 *
39	 * Publication transactions for the earlier Witness verticals are defined
40	 * against their exact predecessor state. Now that the published aggregate has
41	 * advanced to the LinkFree browser proof, those transactions are replayed
42	 * against a staged copy of the exact pre-append membership rather than against
43	 * a loosened predecessor check.
44	 */
45	export async function preAppendAggregate(root: string): Promise<string> {
46		const aggregate = JSON.parse(
47			await readFile(path.join(root, 'evidence/runs/aggregate.json'), 'utf8'),
48		) as { fixtures: Array<Record<string, unknown>> };
49		const fixtures = aggregate.fixtures.filter(
50			(fixture) => !POST_ZERO_SW_RECEIPT_PATHS.has(fixture.receipt),
51		);
52		if (fixtures.length !== 16)
53			throw new Error(`Pre-append aggregate must hold sixteen members, found ${fixtures.length}`);
54		return `${JSON.stringify({ ...aggregate, fixtures }, null, 2)}\n`;
55	}
